INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT118-S1-Q6$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Maria's Position$batch07$, $batch07$Popular music is bad art because it exaggerates love and so fails to represent reality accurately.$batch07$), (1, $batch07$Theo's Position$batch07$, $batch07$Popular music isn't supposed to reflect reality. It does other artistic jobs, like consoling fantasy and romance.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Maria's argument only works if art has to represent reality accurately to be good. Theo attacks exactly that: popular music can do valuable artistic work without reflecting reality. So the clash is the standard Maria is using.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether art has to represent reality accurately to be good art.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT118-S1-Q6$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Theo says popular music provides consoling fantasies. Theo never says *most good art* does. Maria never talks about consoling illusions at all.$batch07$), ($batch07$B$batch07$, $batch07$Maria believes some bad art (popular music) exaggerates love. Theo never denies that popular music exaggerates love; Theo says it doesn't have to be realistic. So we can't put Theo on the other side.$batch07$), ($batch07$C$batch07$, $batch07$This is the most popular wrong answer. Theo's view is that popular music isn't supposed to reflect reality, not that all art should "always" show reality "as it could be". And Maria wants reality as it is, but says nothing about "as it could be". Neither position is supported.$batch07$), ($batch07$D$batch07$, $batch07$Maria calls popular music bad art *because* it fails to represent reality accurately. Theo says it isn't supposed to reflect reality and still performs artistic functions. So Maria says accuracy is needed for good art, and Theo says it isn't.$batch07$), ($batch07$E$batch07$, $batch07$Both treat popular music as art. Maria calls it "bad art" and Theo talks about its "artistic functions".$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT118-S1-Q6$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
